import {lessons,recipes,workflows,commands,sources} from '../content.js?v=0.3.0';
import {e,sourceLink,command,breadcrumb,pageHead,lessonCard,problemCard,workflowCard,notFound} from '../ui.js?v=0.3.0';

export function workflow(id){const w=workflows.find(x=>x.id===id);if(!w)return notFound();return breadcrumb('workflows','Workflows')+pageHead(e(w.level),e(w.title),e(w.summary))+`<div class="article-layout"><article class="article"><div class="callout"><strong>Before you start</strong><p>${e(w.intro)}</p></div>${w.steps.map((s,i)=>`<section><h2>${i+1}. ${e(s.title)}</h2><p>${e(s.text)}</p>${s.code?command(s.code,s.effect,s.language??'Terminal'):''}</section>`).join('')}<div class="callout success"><strong>Finished when</strong><p>${e(w.verify)}</p></div><div class="callout warning"><strong>Stop condition</strong><p>${e(w.stop)}</p></div>${sourceLink(w.source)}<div class="lesson-next"><a class="button" href="#workflows">← All workflows</a><button class="button" data-share>Copy workflow link</button></div></article><aside class="aside"><div class="aside-inner"><h3>Work at your pace</h3><p>These steps explain a workflow. Commands run only when you choose to run them in your own environment.</p><a href="#lesson/read-plan">Learn to read a plan →</a><a href="#fix">Something went wrong? →</a><p>Source reviewed ${w.reviewed}. Local example targets Terraform 1.4+. Cloud examples have not been executed.</p></div></aside></div>`;}
